<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\SiteSetting; use Illuminate\Http\Request;
class SiteSettingsController extends Controller { private array $keys=['site_title','recipient_name','sender_name','birthday_date','intro_heading','intro_message','contact_email','notification_email','share_message']; public function edit(){ $settings=SiteSetting::whereIn('key',$this->keys)->pluck('value','key');return view('admin.settings.edit',compact('settings'));} public function update(Request $r){$d=$r->validate(['site_title'=>'nullable|string|max:120','recipient_name'=>'nullable|string|max:120','sender_name'=>'nullable|string|max:120','birthday_date'=>'nullable|date','intro_heading'=>'nullable|string|max:180','intro_message'=>'nullable|string|max:2000','contact_email'=>'nullable|email|max:180','notification_email'=>'nullable|email|max:180','share_message'=>'nullable|string|max:500']);foreach($this->keys as $key) SiteSetting::updateOrCreate(['key'=>$key],['value'=>$d[$key]??null]);return back()->with('status','Site settings saved.');} }
